#!/usr/bin/env bash
# Install a git pre-commit hook that runs the parked-plans guard
# locally so the guard fires before a push, not just in CI.
#
# Usage: bash scripts/install_parked_plans_hook.sh
#
# Idempotent — safe to run multiple times.
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
HOOK="$REPO_ROOT/.git/hooks/pre-commit"

cat > "$HOOK" <<'EOF'
#!/usr/bin/env bash
# AUTOGENERATED by scripts/install_parked_plans_hook.sh.
# Refuses to commit if a parked plan is being executed.
set -e
cd "$(git rev-parse --show-toplevel)/backend"
if ! python -m pytest tests/test_parked_plans.py -q --no-header 2>&1; then
    echo ""
    echo "❌ pre-commit refused: a parked plan is being implemented."
    echo "   Read PARKED_PLANS.json and either revert the change or"
    echo "   flip that plan's status to 'unparked' first."
    exit 1
fi
EOF

chmod +x "$HOOK"
echo "installed: $HOOK"
